{"findings":[{"tipo":"GC","causa_raiz":"Alocação excessiva de memória dinâmica gerenciada (~6.7 MB acumulados/gerados), engatilhando uma coleta de lixo síncrona (GC.Collect) que bloqueou a CPU por 23.18 ms, quase consumindo todo o orçamento de frame de 27.0 ms sozinho. Isso ocorre tipicamente devido à criação/destruição contínua de GameObjects sem Object Pooling, uso de LINQ em loops de atualização ou geração frequente de arrays e strings na heap.","codigo_refatorado":"using System.Collections.Generic;
using UnityEngine;

public class ObjectPoolManager : MonoBehaviour
{
    public static ObjectPoolManager Instance { get; private set; }

    [System.Serializable]
    public class PoolItem
    {
        public GameObject prefab;
        public int initialSize = 100;
    }

    [SerializeField] private List<PoolItem> poolsToPrewarm = new List<PoolItem>();
    private readonly Dictionary<int, Queue<GameObject>> poolDictionary = new Dictionary<int, Queue<GameObject>>();

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        PrewarmPools();
    }

    private void PrewarmPools()
    {
        foreach (var item in poolsToPrewarm)
        {
            if (item.prefab == null) continue;
            int key = item.prefab.GetInstanceID();
            if (!poolDictionary.ContainsKey(key))
            {
                poolDictionary[key] = new Queue<GameObject>(item.initialSize);
            }

            for (int i = 0; i < item.initialSize; i++)
            {
                GameObject obj = Instantiate(item.prefab, transform);
                obj.SetActive(false);
                poolDictionary[key].Enqueue(obj);
            }
        }
    }

    public GameObject Spawn(GameObject prefab, Vector3 position, Quaternion rotation)
    {
        int key = prefab.GetInstanceID();
        if (!poolDictionary.ContainsKey(key))
        {
            poolDictionary[key] = new Queue<GameObject>();
        }

        GameObject obj;
        if (poolDictionary[key].Count > 0)
        {
            obj = poolDictionary[key].Dequeue();
        }
        else
        {
            obj = Instantiate(prefab, transform);
        }

        obj.transform.SetPositionAndRotation(position, rotation);
        obj.SetActive(true);
        return obj;
    }

    public void Despawn(GameObject prefab, GameObject instance)
    {
        instance.SetActive(false);
        int key = prefab.GetInstanceID();
        if (!poolDictionary.ContainsKey(key))
        {
            poolDictionary[key] = new Queue<GameObject>();
        }
        poolDictionary[key].Enqueue(instance);
    }
}","explicacao_didatica":"O Coletor de Lixo (GC) da Unity atua como um faxineiro: quando você cria objetos temporários com frequência (como projéteis, efeitos ou textos dinâmicos), a memória fica cheia de lixo. Quando a Unity precisa limpar essa memória de uma só vez, o jogo congela (neste caso, por 23 milissegundos). A solução é usar o padrão 'Object Pooling': em vez de instanciar (Instantiate) e destruir (Destroy) itens a todo instante, nós pré-criamos esses objetos no início e apenas os ativamos e desativamos conforme o uso, zerando a criação de lixo e eliminando os travamentos."}],"dicas_level_design":null}

